const crypto = require('crypto');
const express = require('express');
const session = require('express-session');
const argon2 = require('argon2');
const { RateLimiterMemory } = require('rate-limiter-flexible');

const isProd = process.env.NODE_ENV === 'production';

if (isProd && !process.env.SESSION_SECRET) {
  throw new Error('SESSION_SECRET must be set in production');
}

const app = express();

// Behind a reverse proxy, set this so req.ip is the client and not the proxy;
// otherwise every user shares one rate-limit bucket.
if (process.env.TRUST_PROXY) app.set('trust proxy', Number(process.env.TRUST_PROXY));

app.use(express.json({ limit: '10kb' }));

app.use(
  session({
    name: 'sid',
    secret: process.env.SESSION_SECRET || crypto.randomBytes(32).toString('hex'),
    resave: false,
    saveUninitialized: false,
    // Default MemoryStore is per-process and leaks; use Redis/Postgres in production.
    cookie: {
      httpOnly: true,
      sameSite: 'lax',
      secure: isProd,
      maxAge: 1000 * 60 * 60 * 8,
    },
  })
);

// --- User store (swap for a real database) ---------------------------------

const users = new Map(); // username -> { id, username, passwordHash }

const ARGON2_OPTIONS = { type: argon2.argon2id, memoryCost: 19456, timeCost: 2, parallelism: 1 };

// Verified against when the username is unknown, so response time doesn't
// reveal which accounts exist.
const dummyHash = argon2.hash(crypto.randomBytes(16).toString('hex'), ARGON2_OPTIONS);

function parseCredentials(body) {
  const { username, password } = body || {};
  if (typeof username !== 'string' || typeof password !== 'string') return null;
  const name = username.trim().toLowerCase();
  if (!name || name.length > 64 || password.length > 256) return null;
  return { username: name, password };
}

// --- Rate limiting ----------------------------------------------------------

const WINDOW_SECONDS = 15 * 60;

// Stops guessing one account's password from one address.
const limitByUserAndIp = new RateLimiterMemory({
  keyPrefix: 'login_user_ip',
  points: 5,
  duration: WINDOW_SECONDS,
  blockDuration: WINDOW_SECONDS,
});

// Stops one address spraying passwords across many accounts.
const limitByIp = new RateLimiterMemory({
  keyPrefix: 'login_ip',
  points: 50,
  duration: WINDOW_SECONDS,
  blockDuration: WINDOW_SECONDS,
});

function tooManyAttempts(res, limiterRes) {
  const retryAfter = Math.max(1, Math.ceil(limiterRes.msBeforeNext / 1000));
  res.set('Retry-After', String(retryAfter));
  return res.status(429).json({ error: 'Too many failed login attempts. Try again later.' });
}

// --- Routes -----------------------------------------------------------------

app.post('/register', async (req, res) => {
  const creds = parseCredentials(req.body);
  if (!creds || creds.password.length < 8) {
    return res.status(400).json({ error: 'Username and a password of at least 8 characters are required.' });
  }
  if (users.has(creds.username)) {
    return res.status(409).json({ error: 'Username is taken.' });
  }
  const passwordHash = await argon2.hash(creds.password, ARGON2_OPTIONS);
  const user = { id: crypto.randomUUID(), username: creds.username, passwordHash };
  users.set(user.username, user);
  res.status(201).json({ id: user.id, username: user.username });
});

app.post('/login', async (req, res) => {
  const creds = parseCredentials(req.body);
  if (!creds) return res.status(400).json({ error: 'Username and password are required.' });

  const ipKey = req.ip;
  const userIpKey = `${creds.username}_${req.ip}`;

  // Charge the attempt before checking the password, and refund on success.
  // Checking first and charging after would let concurrent requests slip past the limit.
  try {
    await limitByIp.consume(ipKey);
    await limitByUserAndIp.consume(userIpKey);
  } catch (rejected) {
    if (rejected instanceof Error) throw rejected;
    return tooManyAttempts(res, rejected);
  }

  const user = users.get(creds.username);
  const valid = await argon2.verify(user ? user.passwordHash : await dummyHash, creds.password);

  if (!user || !valid) {
    return res.status(401).json({ error: 'Invalid username or password.' });
  }

  await limitByUserAndIp.delete(userIpKey);
  await limitByIp.reward(ipKey, 1);

  // New session ID on privilege change, to prevent session fixation.
  await new Promise((resolve, reject) => req.session.regenerate((err) => (err ? reject(err) : resolve())));
  req.session.userId = user.id;
  req.session.username = user.username;

  res.json({ id: user.id, username: user.username });
});

function requireAuth(req, res, next) {
  if (!req.session.userId) return res.status(401).json({ error: 'Not authenticated.' });
  next();
}

app.get('/me', requireAuth, (req, res) => {
  res.json({ id: req.session.userId, username: req.session.username });
});

app.post('/logout', (req, res, next) => {
  req.session.destroy((err) => {
    if (err) return next(err);
    res.clearCookie('sid');
    res.status(204).end();
  });
});

app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({ error: 'Internal server error.' });
});

if (require.main === module) {
  const port = process.env.PORT || 3000;
  app.listen(port, () => console.log(`Listening on http://localhost:${port}`));
}

module.exports = app;

